const projects = [
  {id: 'p2', dir: 'p2-multiplayer-web-game', req: 'p2-multiplayer-game.md'},
  {id: 'p3', dir: 'p3-plugin-harness', req: 'p3-plugin-harness.md'},
  {id: 'p4', dir: 'p4-chrome-agent', req: 'p4-chrome-agent.md'},
  {id: 'p5', dir: 'p5-mcp-terminal', req: 'p5-mcp-terminal.md'},
  {id: 'p6', dir: 'p6-p2p-chat', req: 'p6-p2p-chat.md'}
]
const schema = JSON.stringify({
  type: 'object',
  properties: {
    project: {type: 'string'},
    verdict: {type: 'string', enum: ['ready', 'gaps', 'blocked']},
    acceptance_note: {type: 'string'},
    links_and_notes: {type: 'string'},
    published_urls: {type: 'array', items: {type: 'object', properties: {url: {type: 'string'}, http_status: {type: 'string'}, serves_product: {type: 'string'}}, required: ['url', 'http_status', 'serves_product']}},
    promo_assets: {type: 'string'},
    gaps: {type: 'array', items: {type: 'string'}},
    fixes: {type: 'array', items: {type: 'string'}},
    report_path: {type: 'string'}
  },
  required: ['project', 'verdict', 'acceptance_note', 'links_and_notes', 'published_urls', 'promo_assets', 'gaps', 'fixes', 'report_path']
})
const results = await parallel('Audit delivery readiness of p2-p6', () => projects.map(p => agent(
  'You are auditing exactly ONE project for delivery readiness: ' + p.id + ' in /Users/wesley/Documents/manus/' + p.dir + ' on this macOS machine.\n' +
  'This is a READ-ONLY audit. Do NOT modify, create, move, commit or delete anything except your one report file. Do NOT run builds, installs, dev servers, browsers that take keyboard focus, audio, or anything that takes over the screen or keyboard. Network checks with curl are fine. Finish within 8 minutes.\n\n' +
  'Delivery requirements to check against (from the reviewer):\n' +
  '1. The submission may include a short ACCEPTANCE NOTE explaining how to run and how to review the work.\n' +
  '2. Extra information such as PUBLISHED URLs goes in a section titled "Links and notes".\n' +
  '3. The published-URL requirement implies the product must be DEPLOYED somewhere a reviewer can access (a public URL that works without the author\'s machine).\n' +
  'Also read the project brief at /Users/wesley/Documents/manus/docs/requirements/' + p.req + ' and the shared plan /Users/wesley/Documents/manus/docs/requirements/00-parallel-plan.md for project-specific delivery expectations.\n\n' +
  'Steps: (a) list the project tree (skip node_modules, .git, build outputs, .worktrees internals except README-type docs) and read README/ACCEPTANCE/DELIVERY/pitch-type docs; (b) does an acceptance note exist, and does it cover both running and reviewing; (c) does a "Links and notes" section exist (exact or near-exact heading) and where; (d) collect every published/deployed URL mentioned in the project or in /Users/wesley/Documents/manus/p7-promo-assets/' + p.id + '/ and check each with `curl -sS -o /dev/null -w "%{http_code}" -L --max-time 15 <url>`, then fetch the page body briefly to confirm it serves this product (not an error or placeholder); (e) list what exists in /Users/wesley/Documents/manus/p7-promo-assets/' + p.id + '/ (promo video, pitch, screenshots); (f) list concrete gaps and the smallest fixes, each naming the file to change.\n' +
  'Verdict: ready = acceptance note + Links and notes + at least one working public URL that serves the product; gaps = fixable omissions; blocked = no deployment or a broken URL.\n' +
  'Write a concise Markdown report to /Users/wesley/Documents/manus/docs/audits/2026-10-18-' + p.id + '.md (create docs/audits if needed) and return that exact path in report_path, plus the structured fields.',
  {brief: 'Audit ' + p.id + ' (' + p.dir + ') delivery readiness', sandbox: 'shared'}
)), {schema})
const failures = results.map((r, i) => r.ok ? null : {project: projects[i].id, code: r.error.code, message: r.error.message}).filter(Boolean)
return {audits: results.filter(r => r.ok).map(r => r.value), failures}

